window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-19091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάλπος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra θ · nº geral 19091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calor do sol ♦ τὰ θάλπη 2 ardor (palavra, sentimento). 〈θάλπω〉</p></section></article>\n<article id=\"entry-dgp-19092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάλπω</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra θ · nº geral 19092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θάλψω, aor. ἔθαλψα, perf. desus., part. aor. pas. θαλφθείς) 1 aquecer; esquentar 2 chocar (ovos) 3 aquecer ao sol; fazer secar 4 excitar; inflamar; abrasar (de paixão, de desejo) 5 reaquecer com afeição; cuidar; mimar 6 confortar 7 intr. manter-se quente; ficar vigoroso, forte 8 deixar-se mimar, deixar-se enganar.</p></section></article>\n<article id=\"entry-dgp-19093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαλπωρή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra θ · nº geral 19093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calor suave 2 tudo o que aquece o coração; conforto; consolo. 〈θάλπω〉</p></section></article>\n<article id=\"entry-dgp-19094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαλύσια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra θ · nº geral 19094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oferta das primícias ♦ τὰ Θαλύσια 2 Talísias, festa da colheita. 〈θάλλω〉</p></section></article>\n<article id=\"entry-dgp-19095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμά</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra θ · nº geral 19095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 muitas vezes; frequentemente 2 em grande quantidade.</p></section></article>\n<article id=\"entry-dgp-19096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάμβευς</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra θ · nº geral 19096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de θάμβος.</p></section></article>\n<article id=\"entry-dgp-19097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra θ · nº geral 19097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐθάμβουν, fut. desus., aor. ἐθάμβησα, perf. τεθάμβηκα; pas. aor. ἐθαμβήθην, perf. τεθάμβημαι) 1 estar pasmado, atônito 2 olhar algo com espanto, com surpresa 3 causar espanto ♦ méd. pas. 4 espantar-se; assombrar-se; ficar atônito. 〈θάμβος〉</p></section></article>\n<article id=\"entry-dgp-19098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάμβος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra θ · nº geral 19098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">surpresa extrema; espanto; estupor.</p></section></article>\n<article id=\"entry-dgp-19099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμβόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra θ · nº geral 19099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θαμβέω-ῶ.</p></section></article>\n<article id=\"entry-dgp-19100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμέες</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra θ · nº geral 19100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pl. nom., dat. θάμεσι e ac. θαμέας) = θαμειαί.</p></section></article>\n<article id=\"entry-dgp-19101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμειαί</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra θ · nº geral 19101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) só pl. nom. e ac. θαμειάς 1 numerosas 2 freqüentes; ininterruptas. 〈θαμά〉</p></section></article>\n<article id=\"entry-dgp-19102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμέσι</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra θ · nº geral 19102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαμέες.</p></section></article>\n<article id=\"entry-dgp-19103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra θ · nº geral 19103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 vir freqüentemente a, dat. ou εἰς e ac. 2 ser assíduo em, ἐν ou ἐπί e dat. 3 ter por hábito, part.: οὐ δὲ θαμίζεις ἡμῖν καταβαίνων εἰς τὸν Πειραιᾶ plat. a nosso ver não tens por hábito vir até o Pireu 4 freqüentar, dat. 〈θαμά〉</p></section></article>\n<article id=\"entry-dgp-19104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαμινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra θ · nº geral 19104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 freqüente 2 apertado em fileiras ♦ θα­μινά adv. 3 freqüentemente. 〈θαμά〉</p></section></article>\n<article id=\"entry-dgp-19105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάμνος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra θ · nº geral 19105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 arbusto; arvoredo 2 galho com ramos. 〈θαμά〉</p></section></article>\n<article id=\"entry-dgp-19106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανάσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra θ · nº geral 19106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mortal; mortífero; letal 2 de morte 3 próximo da morte; moribundo 4 morto ♦ τὰ θανάσιμα 5 venenos. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra θ · nº geral 19107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θανατιάω.</p></section></article>\n<article id=\"entry-dgp-19108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατηφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra θ · nº geral 19108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mortífero; mortal ♦ τὸ θανατη­φόρον 2 canto que prenuncia a morte. 〈θάνατος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-19109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra θ · nº geral 19109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desejar morrer 2 estar para morrer. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra θ · nº geral 19110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de morte; mortal 2 capital (pena, processo, lei). 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra θ · nº geral 19111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mortífero; mortal. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάνατόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra θ · nº geral 19112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. para a morte. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάνατος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra θ · nº geral 19113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 morte 2 pena de morte; execução capital 3 cadáver ♦ ὁ Θάνατος 4 Morte, person. ♦ οἱ θάνατοι 5 tipos de mortes 6 assassínio de muitos ou de um só. 〈θνῄσκω〉</p></section></article>\n<article id=\"entry-dgp-19114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατούσια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra θ · nº geral 19114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festa dos mortos. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra θ · nº geral 19115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θανατηφόρος.</p></section></article>\n<article id=\"entry-dgp-19116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 69 na letra θ · nº geral 19116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 matar 2 levar à morte; condenar à morte 3 (doença) causar a morte; ser letal 4 bíbl. estar morto. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανατώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 70 na letra θ · nº geral 19117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que provoca a morte; mortal. 〈θάνατος〉</p></section></article>\n<article id=\"entry-dgp-19118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανάτωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 71 na letra θ · nº geral 19118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 condenação à morte 2 execução capital. 〈θανατόω〉</p></section></article>\n<article id=\"entry-dgp-19119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανέειν</h1><div class=\"entry-meta\"><span>DGP · ordem 72 na letra θ · nº geral 19119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = θανεῖν.</p></section></article>\n<article id=\"entry-dgp-19120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανέεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 73 na letra θ · nº geral 19120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. ép. de θνῄσκω.</p></section></article>\n<article id=\"entry-dgp-19121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θανεῖν,</h1><div class=\"entry-meta\"><span>DGP · ordem 74 na letra θ · nº geral 19121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. θανέειν, inf. aor. de θνῄσκω.</p></section></article>\n<article id=\"entry-dgp-19122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάνῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 75 na letra θ · nº geral 19122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. subj. aor.2 ép. de θνῄσκω.</p></section></article>\n<article id=\"entry-dgp-19123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάομαι1</h1><div class=\"entry-meta\"><span>DGP · ordem 76 na letra θ · nº geral 19123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. θῆσθαι, aor. poét. θησάμην) 1 sugar; chupar 2 amamentar 3 ordenhar.</p></section></article>\n<article id=\"entry-dgp-19124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάομαι2</h1><div class=\"entry-meta\"><span>DGP · ordem 77 na letra θ · nº geral 19124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. olhar; contemplar.</p></section></article>\n<article id=\"entry-dgp-19125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαπτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 78 na letra θ · nº geral 19125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de θάπτω.</p></section></article>\n<article id=\"entry-dgp-19126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 79 na letra θ · nº geral 19126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θάψω, aor. ἔθαψα, perf. desus.; pas. fut.2 ταφήσομαι, aor. ἐθάφθην, aor.2 ἐτάφην, perf. τέθαμμαι, fut. ant. τεθάψομαι) 1 sepultar 2 prestar honras fúnebres a alguém, ac. 3 celebrar o rito funerário (enterrar ou cremar).</p></section></article>\n<article id=\"entry-dgp-19127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θαργήλια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 80 na letra θ · nº geral 19127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Targélias, festas em honra de Apolo e Ártemis.</p></section></article>\n<article id=\"entry-dgp-19128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θαργηλιών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 81 na letra θ · nº geral 19128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Targelião, no calendário ateniense, mês das Targélias (metade de maio a metade de junho).</p></section></article>\n<article id=\"entry-dgp-19129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρραλέος,</h1><div class=\"entry-meta\"><span>DGP · ordem 82 na letra θ · nº geral 19129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσαλέος, α, ον 1 cheio de confiança; resoluto; ousado 2 confiante em algo, περί e ac., para fazer algo, inf. 3 atrevido; insolente 4 que se pode ousar; seguro; sem perigo: ἀσφαλὲς καὶ θαρραλέον ἐστί plut. é seguro e sem risco, inf. 5 que inspira confiança ♦ τὸ θαρραλέον 6 confiança; ousadia; resolução: ἐν τῷ θαρσαλέῳ εἶναι estar tranqüilo, em segurança, quanto a algo, περί e ac. ♦ τὰ θαρραλέα 7 situações sem risco. 〈θάρρος〉</p></section></article>\n<article id=\"entry-dgp-19130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρραλεότης,</h1><div class=\"entry-meta\"><span>DGP · ordem 83 na letra θ · nº geral 19130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσαλεότης, ητος (ἡ) confiança; ousadia. 〈θαρραλέος〉</p></section></article>\n<article id=\"entry-dgp-19131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρραλέως,</h1><div class=\"entry-meta\"><span>DGP · ordem 84 na letra θ · nº geral 19131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσαλέως adv. com ousadia; com confiança; com resolução.</p></section></article>\n<article id=\"entry-dgp-19132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρρέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 85 na letra θ · nº geral 19132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσέω-ῶ 1 estar cheio de confiança; ser confiante; ser destemido: θάρσει coragem! tenha confiança!, θάρρει plat. ânimo! coragem! i.e., não há nada a temer 2 enfrentar com confiança; não temer, ac.: τὰς μὲν μάχας θαρρεῖτε xen. afrontai com coragem as batalhas, θάνατον θ. plat. não temer a morte, θάρρος θ. plat. alimentar confiança, τὸ τεθαρρηκός ou τὸ θαρροῦν plut. a confiança 3 ter confiança em alguém ou algo, dat., ἐπί e dat. ou διά ou πρός e ac., ou or. inf. ou conj. (ὅτι) 4 ter coragem de, περί, ὑπέρ e gen., ἐπί e dat., πρός e ac. 5 tard. inspirar confiança em, ac. 〈θάρρος〉</p></section></article>\n<article id=\"entry-dgp-19133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρρος,</h1><div class=\"entry-meta\"><span>DGP · ordem 86 na letra θ · nº geral 19133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θάρσος, εος-ους (τό) 1 confiança; resolução; coragem 2 ousadia; audácia; ardor 3 atrevimento; insolência 4 fonte ou motivo de confiança.</p></section></article>\n<article id=\"entry-dgp-19134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρρούντως,</h1><div class=\"entry-meta\"><span>DGP · ordem 87 na letra θ · nº geral 19134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσούντως adv. com confiança, com ousadia. 〈θαρρέω〉</p></section></article>\n<article id=\"entry-dgp-19135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρρύνω,</h1><div class=\"entry-meta\"><span>DGP · ordem 88 na letra θ · nº geral 19135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. θαρσύνω (impf. ἐθάρρυνον, fut. θαρρυνῶ, aor. ἐθάρρυνα, perf. desus.) 1 encorajar; animar; inspirar coragem ou ousadia 2 ter coragem; ter confiança. 〈θάρρος〉</p></section></article>\n<article id=\"entry-dgp-19136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσαλέος</h1><div class=\"entry-meta\"><span>DGP · ordem 89 na letra θ · nº geral 19136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρραλέος.</p></section></article>\n<article id=\"entry-dgp-19137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσαλεότης</h1><div class=\"entry-meta\"><span>DGP · ordem 90 na letra θ · nº geral 19137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρραλεότης.</p></section></article>\n<article id=\"entry-dgp-19138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσαλέως</h1><div class=\"entry-meta\"><span>DGP · ordem 91 na letra θ · nº geral 19138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρραλέως.</p></section></article>\n<article id=\"entry-dgp-19139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρσευς</h1><div class=\"entry-meta\"><span>DGP · ordem 92 na letra θ · nº geral 19139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de θάρσος.</p></section></article>\n<article id=\"entry-dgp-19140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσέω</h1><div class=\"entry-meta\"><span>DGP · ordem 93 na letra θ · nº geral 19140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρρέω.</p></section></article>\n<article id=\"entry-dgp-19141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρσησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 94 na letra θ · nº geral 19141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confiança; coragem. 〈θαρσέω〉</p></section></article>\n<article id=\"entry-dgp-19142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρσος</h1><div class=\"entry-meta\"><span>DGP · ordem 95 na letra θ · nº geral 19142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θάρρος.</p></section></article>\n<article id=\"entry-dgp-19143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσούντως</h1><div class=\"entry-meta\"><span>DGP · ordem 96 na letra θ · nº geral 19143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρρούντως.</p></section></article>\n<article id=\"entry-dgp-19144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσύνεσκε</h1><div class=\"entry-meta\"><span>DGP · ordem 97 na letra θ · nº geral 19144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de θαρσύνω.</p></section></article>\n<article id=\"entry-dgp-19145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάρσυνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 98 na letra θ · nº geral 19145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de ousadia 2 cheio de confiança em, dat. 〈θάρσος〉</p></section></article>\n<article id=\"entry-dgp-19146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαρσύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 99 na letra θ · nº geral 19146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. θαρρύνω.</p></section></article>\n<article id=\"entry-dgp-19147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 100 na letra θ · nº geral 19147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Taso: Θ. λίθος plut. a pedra de Taso, i.e., o mármore ♦ ἡ Θασία [ἅλμη] 2 molho de Taso. 〈θάσος〉</p></section></article>\n<article id=\"entry-dgp-19148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θάσος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 101 na letra θ · nº geral 19148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Taso, ilha e cidade do mar da Trácia.</p></section></article>\n<article id=\"entry-dgp-19149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 102 na letra θ · nº geral 19149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) estar sentado: θ. θρόνον sóf. estar sentado em um trono, θ. ἐπὶ θύραις ar. estar sentado junto às portas. 〈θᾶκος〉</p></section></article>\n<article id=\"entry-dgp-19150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θᾶσσων,</h1><div class=\"entry-meta\"><span>DGP · ordem 103 na letra θ · nº geral 19150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. θάττων, ων, ον gen. ονος comp. de ταχύς.</p></section></article>\n<article id=\"entry-dgp-19151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάτερα, θάτερον, θατέρω, θατέρῳ</h1><div class=\"entry-meta\"><span>DGP · ordem 104 na letra θ · nº geral 19151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἕτερον.</p></section></article>\n<article id=\"entry-dgp-19152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαῦμα,</h1><div class=\"entry-meta\"><span>DGP · ordem 105 na letra θ · nº geral 19152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. θῶμα ou θωῦμα, ατος (τό) 1 objeto de admiração; coisa estranha; maravilha: τοῖσι δ᾽ ἰφθίμην Περὼ τέκε, θαῦμα βροτοῖσι hom. depois deles gerou a vigorosa Pero, uma maravilha para os mortais, θαῦμά γ᾽ οὐδέν ou οὐδέν γε θαῦμα sóf. não há nada de estranho 2 espanto; admiração: θαῦμα μ᾽ ἔχει ou ὑποδύεται o espanto toma conta de mim, θαῦμα ἔχω sóf. estou surpreso, pasmo, ἐν θαύματι εἶναι ou γενέσθαι her. ser tomado de espanto, θῶυμα ποιεῖσθαι her. ou ἐν θαύματι ποιεῖσθαι plut. espantar-se ou maravilhar-se de algo, ac., gen. ou περί e gen. 3 espetáculo extraordinário (prestidigitação, acrobacia) 4 pl. coisa muito difícil de fazer; movimento de destreza; piruetas 5 crist. milagre.</p></section></article>\n<article id=\"entry-dgp-19153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάζεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 106 na letra θ · nº geral 19153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de θαυμάζω.</p></section></article>\n<article id=\"entry-dgp-19154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 107 na letra θ · nº geral 19154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θαυμάσομαι, rar. θαυμάσω, aor. ἐθαύ­μασα, perf. τεθαύμακα; pas. aor. ἐθαυμάσθην, perf. τε­θαύμασμαι) ativa e média 1 ficar maravilhado; pasmar 2 olhar com admiração, com respeito; admirar; maravilhar-se com alguém ou algo, ac., por algo, gen., ἀπό e gen., ou ἐπί e dat. 3 ficar admirado; espantar-se; estranhar; surpreender-se com algo ou alguém, gen. ou ac. ou dat., ou part., ou or. conj. (ὅτι, ὡς, εἰ) 4 admirar-se; perguntar-se com admiração; ver com admiração, or. inf. ou inter. 5 prestar honras; venerar passiva 6 ser objeto de espanto 1 ἡμεῖς δ᾽ ἑσταότες θαυμάζομεν hom. e nós, imóveis, estávamos maravilhados 2 Πρίαμος θαύμαζεν (ép.) Ἀχιλλέα hom. Príamo olhava Aquiles com admiração, θαυμάζων ἦστο πτόλεμόν τε μάχην τε hom. permanecia sentado, admirando a guerra e o combate, τοὺς ἀγγέλλοντας τὰ τοιαῦτα τῆς τόλμης οὐ θαυμάζω tuc. não admiro por sua audácia os que anunciam tais coisas, αὐτὸν ὥσπερ θεὸν ἐθαυμάζομεν ἐπὶ σοφίᾳ plat. como a um deus o admirávamos pela sabedoria, θ. ἀπὸ τοῦ σώματος τὸν νεανίσκον plut. admirar o rapazinho por seu belo físico 3 θαυμάζω τῶν ταύτην τὴν γνώμην ἐχόντων isócr. espanto-me com os que são dessa opinião, θαυμάζω δὲ μάλιστα τούτου τῆς διανοίας lís. espanto-me sobretudo com a mentalidade dele, θαυμάζω τῇ ἀποκλῄσει μου τῶν πυλῶν tuc. espanta-me que as portas estejam fechadas para mim, ὃ δ᾽ ἐθαύμασά σου λέγοντος plat. estranhei que tivesses dito isso, θαυμάζω τῶν προθέντων αὖθις περὶ Μυτιληναίων λέγειν tuc. fico admirado com os que propuseram tratar novamente dos habitantes de Mitilene, θαυμάζειν ὡς οὔπω πάρεισιν tuc. estranhar que eles ainda não estivessem presentes, θ. ὅτι οἱ φιλόσοφοι οὐ τιμῶνται ἐν ταῖς πόλεσι plat. surpreender-se com o fato de que os filósofos não são honrados em nossas cidades, ὑμῶν θαυμάζω εἰ μὴ βοηθήσετε ὑμῖν αὐτοῖς xen. quanto a vós, o que me surpreende é que não prestareis socorro a vós próprios, τὸ μηδὲν θαυμάζειν plut. não espantar-se com nada 4 θαυμάζω ὅστις ἔσται ὁ ἀντερῶν tuc. pergunto-me admirado quem será o contestador, πενθεῖν οὔ σε θαυμάζω τύχας eur. não me admira que chores tua sorte 5 ἐθαύμασ᾽ ἄθλιον τύμβον πατρός eur. venerou o túmulo do pai, μηδὲ τὸν πλοῦτον μηδὲ τὴν δόξαν τὴν τούτων θαυμάζετε dem. não venereis nem a riqueza deles nem o renome 6 θαυμάζεται μὴ παρών sóf. é espantoso que ele não esteja presente. 〈θαῦμα〉</p></section></article>\n<article id=\"entry-dgp-19155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 108 na letra θ · nº geral 19155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">admirar, ac. ou or. conj. (εἰ). 〈θαῦμα〉</p></section></article>\n<article id=\"entry-dgp-19156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 109 na letra θ · nº geral 19156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 espantoso; maravilhoso; admirável: θ. τοῦ κάλλους xen. admirável pela beleza, θ. προσιδέσθαι pínd. maravilhoso de ver 2 estranho: θαυμάσιον καὶ ἄλογον plat. estranho e absurdo ♦ θαυμάσιον ὅσον ou θαυμάσι᾽ ἡλίκα adv. 3 maravilhosamente ♦ ὦ θαυμάσιε fam. 4 ó homem admirável ♦ τὰ θαυμάσια 5 coisas espantosas; maravilhas. 〈θαῦμα〉</p></section></article>\n<article id=\"entry-dgp-19157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμασίως</h1><div class=\"entry-meta\"><span>DGP · ordem 110 na letra θ · nº geral 19157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. maravilhosamente; admiravelmente; espantosamente: θ. ἔχειν estar disposto para admirar, θ. ὡς ἄθλιος plat. espantosamente infeliz.</p></section></article>\n<article id=\"entry-dgp-19158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 111 na letra θ · nº geral 19158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">admiração; espanto. 〈θαυμάζω〉</p></section></article>\n<article id=\"entry-dgp-19159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμάσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 112 na letra θ · nº geral 19159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ép. de θαυμάζω.</p></section></article>\n<article id=\"entry-dgp-19160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 113 na letra θ · nº geral 19160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de θαυμάζω.</p></section></article>\n<article id=\"entry-dgp-19161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστῆς, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 114 na letra θ · nº geral 19161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">admirador. 〈θαυμάζω〉</p></section></article>\n<article id=\"entry-dgp-19162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 115 na letra θ · nº geral 19162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disposto, inclinado a admirar 2 que exprime admiração (adv. ou interj.). 〈θαυμαστός〉</p></section></article>\n<article id=\"entry-dgp-19163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 116 na letra θ · nº geral 19163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. 1 assombroso; extraordinário; maravilhoso por algo, gen., dat. ou πρός e ac. 2 admirável; excelente: ὦ θαυμαστέ plat. admirável amigo!, ὦ θαυμαστότατοι xen. homens muito admiráveis 3 admirável; digno de honra e veneração (deus) 4 iron. estranho ♦ θαυμαστὸν ὅσον ou ἡλίκον, θαυμαστὸν ou θαυμαστὰ ὡς, θαυμαστὰ ὅσα adv. 5 admiravelmente; maravilhosamente. 〈θαυμάζω〉</p></section></article>\n<article id=\"entry-dgp-19164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 117 na letra θ · nº geral 19164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar espantoso ou admirável 2 bíbl. magnificar; enaltecer ♦ pas. 3 ser visto como um prodígio, uma maravilha. 〈θαυμαστός〉</p></section></article>\n<article id=\"entry-dgp-19165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυμαστῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 118 na letra θ · nº geral 19165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. espantosamente; admiravelmente; extraordinariamente.</p></section></article>\n<article id=\"entry-dgp-19166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυματοποιέω</h1><div class=\"entry-meta\"><span>DGP · ordem 119 na letra θ · nº geral 19166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer maravilhas (ilusionismo, prestidigitação) 2 crist. fazer milagres. 〈θαυματοποιός〉</p></section></article>\n<article id=\"entry-dgp-19167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυματοποιΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 120 na letra θ · nº geral 19167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 ilusionismo; prestidigitação; mágica 2 Ret. estilo que peca por excesso de artifícios de estilo 3 crist. milagre. 〈θαυματοποιός〉</p></section></article>\n<article id=\"entry-dgp-19168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυματοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 121 na letra θ · nº geral 19168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que realiza maravilhas; que cria coisas espantosas ♦ ὁ θαυματοποιός 2 prestidigitador; ilusionista 3 crist. milagreiro. 〈θαῦμα, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-19169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυματουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra θ · nº geral 19169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 realizar maravilhas: τὰ τεθαυμα­τουργημένα fenômenos misteriosos 2 crist. fazer milagres. 〈θαυματουργός〉</p></section></article>\n<article id=\"entry-dgp-19170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θαυματουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra θ · nº geral 19170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz maravilhas. 〈θαῦμα, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-19171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θάψινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 124 na letra θ · nº geral 19171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amarelado; amarelo. 〈θάψος〉</p></section></article>\n<article id=\"entry-dgp-19172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θάψος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 125 na letra θ · nº geral 19172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Tapso, península da Sicília ou cidade da Líbia ♦ ἡ θάψος 2 tapso, planta oriunda de Tapso (Sicília), usada como tintura amarela.</p></section></article>\n<article id=\"entry-dgp-19173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 126 na letra θ · nº geral 19173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deusa: αἱ σεμναὶ θεαί as deusas augustas, ou αἱ ἀνώνυμοι θεαί as deusas não nomeadas, i.e., as Erínias, μεγάλαι θεαί sóf. as grandes deusas, ou δύο τὼ θεώ plat. as duas deusas, i.e., Deméter e Perséfone ♦ adj. 2 divina. 〈θεός〉</p></section></article>\n<article id=\"entry-dgp-19174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέα, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 127 na letra θ · nº geral 19174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. θέη (ἡ) 1 ação de olhar; contemplação: θέαν λαβόντα sóf. tendo visto o espetáculo, θέαν λαβεῖν dar uma olhada, θέης ἄξιος her. digno de ser visto, ἐπὶ τῇ θέᾳ αὑτοῦ xen. à vista dele 2 aspecto; aparência 3 o que se observa; espetáculo; cenário; panorama 4 espetáculo; performance; representação 5 pl. jogos; festivais; espetáculos 6 lugar de onde se contempla; lugar no teatro.</p></section></article>\n<article id=\"entry-dgp-19175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 128 na letra θ · nº geral 19175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deusa. 〈θεός〉</p></section></article>\n<article id=\"entry-dgp-19176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέαμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 129 na letra θ · nº geral 19176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 panorama; vista 2 espetáculo; espetáculo de qualidade: τὰ ἑπτὰ θεάματα plut. as sete maravilhas 3 contemplação. 〈θεάομαι〉</p></section></article>\n<article id=\"entry-dgp-19177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεᾶν</h1><div class=\"entry-meta\"><span>DGP · ordem 130 na letra θ · nº geral 19177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. dór. de θεά.</p></section></article>\n<article id=\"entry-dgp-19178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 131 na letra θ · nº geral 19178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θεάσομαι, aor. ἐθεασάμην, perf. τεθέαμαι, m.-q.-perf. ἐτεθεάμην; aor. pas. ἐθεάθην) 1 olhar; observar; olhar com admiração; contemplar 2 ver; constatar 3 considerar; examinar 4 Mil. passar em revista 5 assistir a; ser espectador de, ac.: θ. πόλεμον her. ser espectador de uma guerra, οἱ θεώμενοι os espectadores. 〈θέα〉</p></section></article>\n<article id=\"entry-dgp-19179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 132 na letra θ · nº geral 19179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de θεάομαι.</p></section></article>\n<article id=\"entry-dgp-19180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 133 na letra θ · nº geral 19180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espectador; observador. 〈θεάομαι〉</p></section></article>\n<article id=\"entry-dgp-19181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 134 na letra θ · nº geral 19181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 visível 2 digno de ser contemplado ou observado. 〈θεάομαι〉</p></section></article>\n<article id=\"entry-dgp-19182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 135 na letra θ · nº geral 19182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 representar em cena 2 tratar como objeto de comédia; expor ao ridículo.</p></section></article>\n<article id=\"entry-dgp-19183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 136 na letra θ · nº geral 19183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de teatro; teatral 2 teatral; pomposo. 〈θέατρον〉</p></section></article>\n<article id=\"entry-dgp-19184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεατρικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 137 na letra θ · nº geral 19184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de maneira teatral.</p></section></article>\n<article id=\"entry-dgp-19185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέατρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 138 na letra θ · nº geral 19185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 teatro, lugar dos espectadores; auditório; platéia 2 teatro, lugar do espetáculo 3 espetáculo 4 pl. os espectadores; platéia; público 5 lugar de reunião, de assembléia. 〈θεάομαι〉</p></section></article>\n<article id=\"entry-dgp-19186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέε</h1><div class=\"entry-meta\"><span>DGP · ordem 139 na letra θ · nº geral 19186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. ép. de θέω.</p></section></article>\n<article id=\"entry-dgp-19187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέειον</h1><div class=\"entry-meta\"><span>DGP · ordem 140 na letra θ · nº geral 19187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = θεῖον2.</p></section></article>\n<article id=\"entry-dgp-19188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέειος</h1><div class=\"entry-meta\"><span>DGP · ordem 141 na letra θ · nº geral 19188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép.= θεῖος2.</p></section></article>\n<article id=\"entry-dgp-19189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεειόω</h1><div class=\"entry-meta\"><span>DGP · ordem 142 na letra θ · nº geral 19189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = θειόω1.</p></section></article>\n<article id=\"entry-dgp-19190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θέεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 143 na letra θ · nº geral 19190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de θέω1.</p></section></article>\n";
